-- inc1a_foundations (docs/pilot/DATA_MODEL.md §3.1-3.4). Generated by
--   npm run db:new-migration -- inc1a_foundations
-- (prisma migrate diff from the af889bf schema to prisma/schema.prisma), then hand-edited in this
-- order: (1) pre-check, (2) the generated DDL unchanged, (3) backfills, (4) CHECK constraints.
-- The file runs as ONE transaction: if any statement fails, nothing is applied.
--
-- The values ADDED to existing enums in (2) (PaymentStatus.REJECTED, LedgerEntryType.CREDIT_ORDER_REVERSAL
-- and DEBIT_REFILL, AlertType.WALLET_CHECK_MISMATCH) are not used anywhere in this file: Postgres refuses
-- a new enum value before it is committed (55P04). Values of the enums CREATED in (2) are fine to use.
--
-- Every backfill is safe to re-run (WHERE ... IS NULL, ON CONFLICT DO NOTHING, NOT EXISTS) and safe on
-- an empty database.
--
-- Changed in place on 2026-10-22, before inc1a reached any shared database (it had run only on test
-- databases): (2) regenerated with the same flow, adding clients.client_request_id and
-- distributors.client_request_id with their unique keys (G15-01, the Idempotency-Key of POST /clients
-- and POST /distributors; new nullable columns, so no backfill); (3) backfill 12 added (G17-03).

-- (1) PRE-CHECK [hand edit; the tested block, with this migration's name in the message]:
--     one store can't be the home store of two distributors (distributors_home_store_id_key below
--     would otherwise fail with a vague error).
DO $$
DECLARE dup text;
BEGIN
  SELECT string_agg(home_store_id::text || ' x' || n, ', ') INTO dup
  FROM (SELECT home_store_id, count(*) AS n FROM distributors
        WHERE home_store_id IS NOT NULL GROUP BY home_store_id HAVING count(*) > 1) d;
  IF dup IS NOT NULL THEN
    RAISE EXCEPTION 'MIGRATION_BLOCKED inc1a: a store is the home store of more than one distributor (%). Give each distributor its own store, run "prisma migrate resolve --rolled-back 20261021195005_inc1a_foundations", then deploy again.', dup;
  END IF;
END $$;

