-- (3) BACKFILLS [hand edit], in the DATA_MODEL §3.4 order. "Tested block" = copied unchanged from
--     the tested design migration.

-- 3.1 Distributor codes D01, D02 ... by created_at (tested block 3b). The super admin may change a
--     code until the distributor's first order.
UPDATE distributors d
SET code = 'D' || lpad(x.rn::text, GREATEST(2, length(x.rn::text)), '0')
FROM (SELECT id, row_number() OVER (ORDER BY created_at, id) AS rn FROM distributors) x
WHERE d.id = x.id AND d.code IS NULL;

-- 3.2 Order numbers per distributor by (created_at, id) (tested block 3c), then the order counter.
UPDATE orders o SET order_no = x.rn
FROM (SELECT id, row_number() OVER (PARTITION BY distributor_id ORDER BY created_at, id) AS rn FROM orders) x
WHERE o.id = x.id AND o.order_no IS NULL;

UPDATE distributors d SET next_order_no = COALESCE((SELECT max(order_no) FROM orders o WHERE o.distributor_id = d.id), 0) + 1;

-- 3.3 Orders the old code already charged keep that charge as their deducted cost. Every other existing
--     order keeps fee_status NONE: no cost was taken, and none will be.
UPDATE orders SET fee_status = 'DEDUCTED', fee_strategy = 'LEGACY_ZONE_PAIR'
WHERE payment_status = 'PAID_VIA_LEDGER' AND fee_status = 'NONE';

-- 3.4 Progress timestamps (tested block 3c, plus the FAILED line).
UPDATE orders o
SET delivered_at = COALESCE(
      (SELECT min(le.created_at) FROM ledger_entries le
        WHERE le.order_id = o.id AND le.entry_type = 'DEBIT_ORDER'),
      o.updated_at),
    delivery_method = 'DRIVER_TAP'
WHERE o.status = 'DELIVERED' AND o.delivered_at IS NULL;

UPDATE orders SET cancelled_at = updated_at WHERE status = 'CANCELLED' AND cancelled_at IS NULL;

UPDATE orders SET failed_at = updated_at WHERE status = 'FAILED' AND failed_at IS NULL;

UPDATE orders o SET assigned_at = t.planned_at
FROM trips t WHERE o.trip_id = t.id AND o.assigned_at IS NULL;

-- 3.5 Payments: remove the blank and self-referencing BANK_MANUAL placeholders and number the top-ups
--     (tested block 3d), then the top-up counter.
UPDATE payments SET provider_txn_id = NULL
WHERE provider_txn_id = '' OR (provider = 'BANK_MANUAL' AND provider_txn_id = id::text);

UPDATE payments p SET request_no = x.rn
FROM (SELECT id, row_number() OVER (PARTITION BY distributor_id ORDER BY created_at, id) AS rn FROM payments) x
WHERE p.id = x.id AND p.request_no IS NULL;

UPDATE distributors d SET next_topup_no = COALESCE((SELECT max(request_no) FROM payments p WHERE p.distributor_id = d.id), 0) + 1;

-- 3.6 Ledger: keys for old rows; link old refill debits by their note, written by
--     filling-orders.service.ts complete() (tested block 3e).
UPDATE ledger_entries SET idempotency_key = 'legacy:' || id::text WHERE idempotency_key IS NULL;

UPDATE ledger_entries le SET filling_order_id = fo.id
FROM filling_orders fo
WHERE le.filling_order_id IS NULL
  AND le.entry_type = 'ADJUSTMENT'
  AND le.note LIKE 'Filling order %'
  AND fo.distributor_id = le.distributor_id
  AND left(fo.id::text, 8) = substring(le.note FROM 15 FOR 8);

-- 3.7 Opening entry wherever the cached balance has no ledger history behind it, so the ledger sum
--     equals the balance, plus an audit row (tested block 3f). Ops checks each one against the bank.
INSERT INTO ledger_entries (id, distributor_id, entry_type, amount_paisa, balance_after_paisa,
                            idempotency_key, reason_code, note, created_at)
SELECT gen_random_uuid(), d.id, 'ADJUSTMENT',
       d.advance_balance_paisa - COALESCE(s.total, 0), d.advance_balance_paisa,
       'opening:' || d.id::text, 'OPENING_BALANCE',
       'Balance difference recorded when wallet history started', now()
FROM distributors d
LEFT JOIN (SELECT distributor_id, sum(amount_paisa) AS total FROM ledger_entries GROUP BY distributor_id) s
       ON s.distributor_id = d.id
WHERE d.advance_balance_paisa <> COALESCE(s.total, 0)
ON CONFLICT (idempotency_key) DO NOTHING;

INSERT INTO audit_logs (id, actor_kind, actor_label, action, resource_type, resource_id, distributor_id, reason, diff, created_at)
SELECT gen_random_uuid(), 'SYSTEM', 'migration:inc1a', 'wallet.opening_entry', 'Distributor',
       le.distributor_id, le.distributor_id, 'Cached balance had no wallet history behind it',
       jsonb_build_object('ledgerEntryId', le.id, 'amountPaisa', le.amount_paisa::text), now()
FROM ledger_entries le
WHERE le.reason_code = 'OPENING_BALANCE'
  AND NOT EXISTS (SELECT 1 FROM audit_logs a WHERE a.action = 'wallet.opening_entry' AND a.resource_id = le.distributor_id);

-- 3.8 Trip stops: the store of pickup stops, and a status from the timestamps (tested block 3g).
UPDATE trip_stops ts SET store_id = t.origin_store_id
FROM trips t WHERE ts.trip_id = t.id AND ts.stop_type = 'STORE_PICKUP' AND ts.store_id IS NULL;

UPDATE trip_stops ts SET status = 'DONE', completed_at = COALESCE(o.delivered_at, ts.departed_at, ts.arrived_at)
FROM orders o
WHERE ts.order_id = o.id AND ts.stop_type = 'DELIVERY' AND o.status = 'DELIVERED' AND ts.status = 'PENDING';

UPDATE trip_stops SET status = 'DONE', completed_at = departed_at
WHERE departed_at IS NOT NULL AND status = 'PENDING';

UPDATE trip_stops SET status = 'ARRIVED'
WHERE arrived_at IS NOT NULL AND departed_at IS NULL AND status = 'PENDING';

UPDATE trip_stops ts SET status = 'CANCELLED', cancelled_at = COALESCE(t.completed_at, now())
FROM trips t WHERE ts.trip_id = t.id AND t.status = 'ABORTED' AND ts.status IN ('PENDING', 'ARRIVED');

-- 3.9 Customer address zones, by the one zone rule used everywhere (tested block 3h): active zones
--     only, border points count, smallest zone first, then oldest.
UPDATE client_addresses ca SET zone_id = (
  SELECT z.id FROM zones z
  WHERE z.is_active AND ST_Covers(z.polygon, ca.location)
  ORDER BY ST_Area(z.polygon) ASC, z.created_at ASC, z.id ASC
  LIMIT 1)
WHERE ca.zone_id IS NULL;

-- 3.10 Customer phones to +923XXXXXXXXX where the pattern is unambiguous (tested inc2 block
--      "3c customer phones", with actor_label migration:inc1a). Anything else stays as typed and gets
--      one client.phone_needs_fix audit row, so it can be listed and fixed.
--      [changed from the tested block] NOT EXISTS stops a re-run from adding a second audit row.
WITH n AS (
  SELECT id,
         CASE
           WHEN d ~ '^03[0-9]{9}$'    THEN '+92' || substr(d, 2)
           WHEN d ~ '^923[0-9]{9}$'   THEN '+' || d
           WHEN d ~ '^00923[0-9]{9}$' THEN '+' || substr(d, 3)
           WHEN d ~ '^3[0-9]{9}$'     THEN '+92' || d
         END AS e164
  FROM (SELECT id, regexp_replace(phone, '[^0-9]', '', 'g') AS d FROM clients) raw)
UPDATE clients c SET phone = n.e164
FROM n WHERE n.id = c.id AND n.e164 IS NOT NULL AND c.phone <> n.e164;

INSERT INTO audit_logs (id, actor_kind, actor_label, action, resource_type, resource_id, distributor_id, reason, created_at)
SELECT gen_random_uuid(), 'SYSTEM', 'migration:inc1a', 'client.phone_needs_fix', 'Client', c.id, c.distributor_id,
       'Phone number is not a Pakistani mobile number; confirmation links cannot be sent', now()
FROM clients c
WHERE c.phone !~ '^\+923[0-9]{9}$'
  AND NOT EXISTS (SELECT 1 FROM audit_logs a WHERE a.action = 'client.phone_needs_fix' AND a.resource_id = c.id);

-- 3.11 Expense types: the six seeded types, an archived type for each old category still in use (so
--      old rows keep their meaning), then each expense's type_id.
INSERT INTO expense_types (id, code, name, name_key, is_system, sort_order, created_at, updated_at) VALUES
  (gen_random_uuid(),'PETROL','Petrol','petrol',true,10,now(),now()),
  (gen_random_uuid(),'MAINTENANCE','Maintenance','maintenance',false,20,now(),now()),
  (gen_random_uuid(),'REPAIRS','Repairs','repairs',false,30,now(),now()),
  (gen_random_uuid(),'TYRES','Tyres','tyres',false,40,now(),now()),
  (gen_random_uuid(),'TOLL_PARKING','Toll/Parking','toll/parking',false,50,now(),now()),
  (gen_random_uuid(),'OTHER','Other','other',true,999,now(),now())
ON CONFLICT (code) DO NOTHING;

INSERT INTO expense_types (id, code, name, name_key, is_system, sort_order, archived_at, created_at, updated_at)
SELECT gen_random_uuid(), 'LEGACY_' || c, initcap(lower(c)), lower(c), false, 900, now(), now(), now()
FROM (SELECT DISTINCT category::text AS c FROM expenses WHERE category::text NOT IN ('FUEL','MAINTENANCE','OTHER')) x
ON CONFLICT (code) DO NOTHING;

UPDATE expenses e SET type_id = t.id FROM expense_types t
WHERE e.type_id IS NULL AND t.code = CASE e.category::text
  WHEN 'FUEL' THEN 'PETROL' WHEN 'MAINTENANCE' THEN 'MAINTENANCE' WHEN 'OTHER' THEN 'OTHER'
  ELSE 'LEGACY_' || e.category::text END;

-- 3.12 Retired alert rules: balances can't go negative, so a DISTRIBUTOR_CREDIT_OVER rule can never
--      fire. Deactivate the existing ones (the API refuses new ones). Safe to re-run.
UPDATE alert_rules SET is_active = false, updated_at = now()
WHERE rule_kind = 'DISTRIBUTOR_CREDIT_OVER' AND is_active;

-- (4) CHECK CONSTRAINTS [hand edit]. Prisma never diffs CHECKs, so later migrations keep them.
ALTER TABLE distributor_zone_prices      ADD CONSTRAINT dzp_base_chk    CHECK (base_paisa >= 0);
ALTER TABLE distributor_zone_price_sizes ADD CONSTRAINT dzps_amount_chk CHECK (per_cylinder_paisa >= 0);
ALTER TABLE distributors
  ADD CONSTRAINT distributors_code_chk     CHECK (code IS NULL OR code ~ '^[A-Z][A-Z0-9]{1,5}$'),
  ADD CONSTRAINT distributors_counters_chk CHECK (next_order_no >= 1 AND next_topup_no >= 1
                                                  AND next_refill_no >= 1 AND next_cylinder_no >= 1);
ALTER TABLE audit_logs    ADD CONSTRAINT audit_logs_actor_chk  CHECK ((actor_kind = 'USER') = (actor_user_id IS NOT NULL));
ALTER TABLE stored_files  ADD CONSTRAINT stored_files_size_chk CHECK (size_bytes > 0);
ALTER TABLE expense_types ADD CONSTRAINT expense_types_name_chk CHECK (char_length(btrim(name)) BETWEEN 2 AND 40);
ALTER TABLE expenses      ADD CONSTRAINT expenses_void_chk     CHECK ((voided_at IS NULL) = (void_reason IS NULL));
-- NOT VALID: new and updated rows are checked; old rows are left alone.
ALTER TABLE orders      ADD CONSTRAINT orders_fee_chk         CHECK (delivery_fee_paisa >= 0 AND (fee_base_paisa IS NULL OR fee_base_paisa >= 0)) NOT VALID;
ALTER TABLE order_lines ADD CONSTRAINT order_lines_counts_chk CHECK (full_count >= 0 AND expected_return_count >= 0) NOT VALID;
ALTER TABLE payments    ADD CONSTRAINT payments_amount_chk    CHECK (amount_paisa > 0) NOT VALID;
ALTER TABLE expenses    ADD CONSTRAINT expenses_amount_chk    CHECK (amount_paisa > 0) NOT VALID;
